class _LidarApplyReservation:
    """Serialize LiDAR result application while dropping stale worker results."""

    def __init__(self, lock: threading.RLock, reserve):
        self._lock = lock
        self._reserve = reserve
        self.active = False

    def __enter__(self):
        self._lock.acquire()
        self.active = bool(self._reserve())
        if not self.active:
            self._lock.release()
        return self.active

    def __exit__(self, exc_type, exc, tb):
        if self.active:
            self._lock.release()
        return False



class LidarApplyTrace:
    """Compact wall/thread/process timeline for slow LiDAR apply diagnostics."""

    def __init__(self, enabled: bool, request_id: int = 0, scan_t: float = 0.0, threshold_ms: float = 0.0):
        self.enabled = bool(enabled)
        self.request_id = int(request_id or 0)
        self.scan_t = float(scan_t or 0.0)
        self.threshold_ms = float(threshold_ms or 0.0)
        self._thread_time = getattr(time, "thread_time", None)
        self._start_wall = time.monotonic()
        self._start_process = time.process_time()
        self._start_thread = self._thread_time() if self._thread_time is not None else None
        self.events: list[dict] = []
        if self.enabled:
            self.mark("trace_start")

    def mark(self, label: str, **fields) -> None:
        if not self.enabled:
            return
        now_wall = time.monotonic()
        now_process = time.process_time()
        now_thread = self._thread_time() if self._thread_time is not None else None
        event = {
            "label": str(label),
            "t_ms": max(0.0, (now_wall - self._start_wall) * 1000.0),
            "process_cpu_ms": max(0.0, (now_process - self._start_process) * 1000.0),
            "thread_cpu_ms": ""
            if now_thread is None or self._start_thread is None
            else max(0.0, (now_thread - self._start_thread) * 1000.0),
            "thread": threading.current_thread().name,
        }
        for key, value in fields.items():
            if isinstance(value, (str, int, float, bool)) or value is None:
                event[str(key)] = value
        self.events.append(event)

    @staticmethod
    def _as_float(value, default: float = 0.0) -> float:
        try:
            if value == "":
                return default
            return float(value)
        except Exception:
            return default

    def gaps(self) -> list[dict]:
        gaps: list[dict] = []
        if len(self.events) < 2:
            return gaps
        previous = self.events[0]
        for current in self.events[1:]:
            wall_ms = max(0.0, self._as_float(current.get("t_ms")) - self._as_float(previous.get("t_ms")))
            process_ms = max(0.0, self._as_float(current.get("process_cpu_ms")) - self._as_float(previous.get("process_cpu_ms")))
            thread_ms = max(0.0, self._as_float(current.get("thread_cpu_ms")) - self._as_float(previous.get("thread_cpu_ms")))
            gaps.append(
                {
                    "from": previous.get("label", ""),
                    "to": current.get("label", ""),
                    "label": f"{previous.get('label', '')}->{current.get('label', '')}",
                    "wall_ms": wall_ms,
                    "process_cpu_ms": process_ms,
                    "thread_cpu_ms": thread_ms,
                    "gap_ms": max(0.0, wall_ms - thread_ms),
                }
            )
            previous = current
        return gaps

    def summary(self, total_wall_ms=None) -> dict:
        if not self.enabled:
            return {
                "enabled": 0,
                "reason": "disabled",
                "event_count": 0,
                "top_gap_ms": "",
                "top_gap_label": "",
                "total_thread_cpu_ms": "",
                "total_wall_ms": "",
            }
        total_wall = self._as_float(total_wall_ms, self.events[-1]["t_ms"] if self.events else 0.0)
        gaps = self.gaps()
        top_gap = max(gaps, key=lambda gap: gap.get("gap_ms", 0.0), default={})
        last_event = self.events[-1] if self.events else {}
        reason = "slow_apply" if total_wall >= self.threshold_ms else "below_threshold"
        return {
            "enabled": 1,
            "reason": reason,
            "event_count": len(self.events),
            "top_gap_ms": top_gap.get("gap_ms", ""),
            "top_gap_label": top_gap.get("label", ""),
            "total_thread_cpu_ms": last_event.get("thread_cpu_ms", ""),
            "total_wall_ms": total_wall,
        }

    def should_emit(self, total_wall_ms=None) -> bool:
        if not self.enabled:
            return False
        total_wall = self._as_float(total_wall_ms, self.events[-1]["t_ms"] if self.events else 0.0)
        return total_wall >= self.threshold_ms

    def record(self, total_wall_ms=None, extra: Optional[dict] = None) -> dict:
        return {
            "request_id": self.request_id,
            "scan_t": self.scan_t,
            "threshold_ms": self.threshold_ms,
            "summary": self.summary(total_wall_ms),
            "extra": dict(extra or {}),
            "events": list(self.events),
            "gaps": self.gaps(),
        }

