def _unpark_passive_measurement_float(measurement: dict, key: str, default: float = 0.0) -> float:
    try:
        value = float(measurement.get(key, default))
    except (TypeError, ValueError):
        return default
    return value if math.isfinite(value) else default


def _unpark_passive_color_measurement_time(measurement: dict) -> float:
    request_t = _unpark_passive_measurement_float(measurement, "request_t", 0.0)
    if request_t > 0.0:
        return request_t
    return _unpark_passive_measurement_float(measurement, "result_t", 0.0)


def _unpark_passive_color_epoch_match(measurement: dict, epochs: list[dict], now: float) -> tuple[dict | None, str]:
    measurement_t = _unpark_passive_color_measurement_time(measurement)
    if measurement_t <= 0.0:
        return None, "missing_time"
    if not epochs:
        return None, "no_stationary_epoch"
    starts = []
    ends = []
    for epoch in epochs:
        start_t = float(epoch.get("start_t", 0.0) or 0.0)
        end_t = float(epoch.get("end_t", 0.0) or 0.0)
        if start_t <= 0.0:
            continue
        effective_end_t = end_t if end_t > 0.0 else now
        starts.append(start_t)
        ends.append(effective_end_t)
        if start_t <= measurement_t <= effective_end_t:
            return epoch, ""
    if starts and measurement_t < min(starts):
        return None, "before_window"
    return None, "outside_stationary"


def _unpark_passive_color_measurement_sample(measurement: dict, now: float, args, epochs: list[dict]) -> tuple[dict | None, str]:
    measurement_id = str(measurement.get("measurement_id", "") or "")
    if not measurement_id:
        return None, "missing_id"
    if not bool(measurement.get("real_measurement", False)):
        return None, "not_real"
    epoch, reason = _unpark_passive_color_epoch_match(measurement, epochs, now)
    if epoch is None:
        return None, reason
    max_age_ms = max(0.0, float(getattr(args, "navigation_color_confirmation_max_measurement_age_ms", 150.0)))
    age_ms = _unpark_passive_measurement_float(measurement, "age_ms", float("nan"))
    if max_age_ms > 0.0 and (not math.isfinite(age_ms) or abs(age_ms) > max_age_ms):
        return None, "stale_frame"
    request_t = _unpark_passive_measurement_float(measurement, "request_t", 0.0)
    result_t = _unpark_passive_measurement_float(measurement, "result_t", 0.0)
    label = str(measurement.get("label", "") or "")
    return {
        "t": now,
        "measurement_id": measurement_id,
        "label": label if label in ("RED", "GREEN") else "OTHER",
        "confidence": _unpark_passive_measurement_float(measurement, "confidence", 0.0),
        "request_t": request_t,
        "result_t": result_t,
        "age_ms": age_ms,
        "epoch_key": str(epoch.get("key", "") or ""),
    }, ""


