    parser.add_argument("--init-scans", type=int, default=8, help="Number of first scans used for initial LiDAR pose search")
    parser.add_argument("--init-max-points", type=int, default=110, help="Maximum stacked scan points used during initial search")
    parser.add_argument("--init-retry-scans", type=int, default=8, help="Rolling scan window kept for repeated initial localization attempts")
