    parser.add_argument("--init-good-match-ratio", type=float, default=0.42, help="Matched point ratio considered strong for initial confidence scoring")
    parser.add_argument("--no-startup-auto-classifier", dest="startup_auto_classifier", action="store_false", help="Disable automatic startup mode/direction classifier before global initial localization")
    parser.add_argument("--startup-auto-scans", type=int, default=10, help="Initial LiDAR scans used by the startup mode/direction classifier")
