    parser.add_argument("--init-parking-start-margin-m", type=float, default=0.12, help="Pose margin around the parking slot where parking-start scoring applies")
    parser.add_argument("--init-parking-min-points", type=int, default=28, help="Minimum map-matched points when starting inside the parking slot")
    parser.add_argument("--init-parking-min-segment-points", type=int, default=6, help="Minimum points before one parking wall counts as visible during initial localization")
    parser.add_argument("--init-parking-min-segments", type=int, default=1, help="Minimum visible parking wall segments required for parking-start scoring")
    parser.add_argument("--init-parking-good-segments", type=int, default=2, help="Visible parking wall count considered strong for parking-start scoring")
