@dataclass(frozen=True)
class LidarScanInput:
    ranges: tuple[float, ...]
    angle_min: float
    angle_increment: float
    range_min: float
    range_max: float
    scan_time: float = 0.0
    time_increment: float = 0.0
    header_stamp_s: float = 0.0
    ros_now_s: float = 0.0
    receive_t: Optional[float] = None


class SchedulerTimingProbe:
    """Optional wakeup-latency probe for diagnosing Python scheduling pressure."""

    def __init__(self, args, shared: SharedTelemetry):
        self.args = args
        self.shared = shared
        self.enabled = bool(getattr(args, "timing_scheduler_probe", False))
        self.hz = max(1.0, float(getattr(args, "timing_scheduler_probe_hz", 100.0) or 100.0))
        self.interval_s = 1.0 / self.hz
        self.stop_event = threading.Event()
        self.thread = None
        self.lock = threading.Lock()
        self.samples = deque(maxlen=max(30, int(self.hz * 3.5)))

    @staticmethod
    def _percentile(values, q: float):
        values = sorted(float(v) for v in values)
        if not values:
            return None
        if len(values) == 1:
            return values[0]
        pos = (len(values) - 1) * float(q) / 100.0
        lo = int(math.floor(pos))
        hi = int(math.ceil(pos))
        if lo == hi:
            return values[lo]
        return values[lo] * (hi - pos) + values[hi] * (pos - lo)

    def start(self) -> None:
        if not self.enabled or self.thread is not None:
            return
        self.thread = threading.Thread(target=self._run, name="scheduler-probe", daemon=True)
        self.thread.start()

    def stop(self) -> None:
        self.stop_event.set()
        thread = self.thread
        if thread is not None:
            try:
                thread.join(timeout=0.4)
            except Exception:
                pass
        self.thread = None

    def _publish(self, now: float, late_ms: float) -> None:
        with self.lock:
            self.samples.append((now, float(late_ms)))
            recent_1s = [v for t, v in self.samples if now - t <= 1.0]
            recent_3s = [v for t, v in self.samples if now - t <= 3.0]
        self.shared.record_metric(
            "scheduler_probe",
            {
                "enabled": 1,
                "configured_hz": self.hz,
                "late_ms": float(late_ms),
                "late_p50_1s_ms": self._percentile(recent_1s, 50.0),
                "late_p95_1s_ms": self._percentile(recent_1s, 95.0),
                "late_max_1s_ms": max(recent_1s) if recent_1s else None,
                "late_p50_3s_ms": self._percentile(recent_3s, 50.0),
                "late_p95_3s_ms": self._percentile(recent_3s, 95.0),
                "late_max_3s_ms": max(recent_3s) if recent_3s else None,
                "sample_count_1s": len(recent_1s),
                "sample_count_3s": len(recent_3s),
                "rate_hz": len(recent_1s),
            },
        )

    def _run(self) -> None:
        next_t = time.monotonic() + self.interval_s
        while not self.stop_event.is_set():
            sleep_s = next_t - time.monotonic()
            if sleep_s > 0.0:
                time.sleep(sleep_s)
            now = time.monotonic()
            late_ms = max(0.0, (now - next_t) * 1000.0)
            try:
                self._publish(now, late_ms)
            except Exception:
                pass
            next_t += self.interval_s
            if next_t < now - self.interval_s:
                next_t = now + self.interval_s


class RobotPerceptionConfig(SimpleNamespace):
    """Attribute-style config namespace using the same CLI defaults as the web test."""


def default_config(**overrides) -> RobotPerceptionConfig:
    config = RobotPerceptionConfig(**vars(parse_args([])))
    for key, value in overrides.items():
        setattr(config, key, value)
    return config


class RobotPerception:
    def __init__(self, args=None, color_analyzer: Optional[CameraColorAnalyzer] = None):
        self.args = args if args is not None else default_config()
        self._runtime_debug_lock = threading.Lock()
        self._runtime_full_web_debug_enabled = bool(getattr(self.args, "web_debug", False))
        self._runtime_lite_web_debug_enabled = False
        self._runtime_camera_web_debug_enabled = bool(getattr(self.args, "camera_web_debug", False))
        self._runtime_camera_web_debug_fps = max(0.1, float(getattr(self.args, "camera_web_debug_fps", 4.0)))
        self.args.camera_web_debug = self._runtime_camera_web_debug_enabled
        self.args.camera_web_debug_fps = self._runtime_camera_web_debug_fps
        initial_anchor = Pose(t=time.monotonic(), x=self.args.start_x, y=self.args.start_y, h=self.args.start_h)
        self.shared = SharedTelemetry(
            max_scan_points=self.args.max_scan_points,
            initial_anchor=initial_anchor,
            pose_history_seconds=self.args.pose_history_s,
            drive_deadman_hold_s=self.args.drive_command_deadman_timeout_s,
        )
        self.initial_localizer = InitialLidarLocalizer(self.args, self.shared)
        self.drift_corrector = LidarDriftCorrector(self.args, self.shared)
        self.lidar_processing_worker = LidarProcessingWorkerClient(self.args)
        self.lidar_pose_worker = None if self.lidar_processing_worker.enabled else LidarPoseWorkerClient(self.args)
        self.cloud_wall_diagnostic_worker = LidarCloudWallDiagnosticWorker(self.args, self.shared)
        self.color_analyzer = color_analyzer if color_analyzer is not None else CameraColorAnalyzer(self.args)
        self._control_payload_last_full_t = 0.0
        self._control_payload_last_light_t = 0.0
        self._control_payload_skipped = 0
        self._web_payload_last_full_t = 0.0
        self._web_payload_cached_count = 0
        self._lidar_processing_apply_lock = threading.RLock()
        self._lidar_processing_apply_stop = threading.Event()
        self._lidar_processing_apply_thread = None
        self._last_lidar_processing_applied_request_id = 0
        self._lidar_scan_log_lock = threading.Lock()
        self._lidar_scan_log_file = None
        self._lidar_scan_log_writer = None
        self._lidar_scan_log_count = 0
        self._lidar_scan_log_flush_every = max(1, int(getattr(self.args, "lidar_scan_debug_log_flush_every", 10)))
        self._lidar_scan_log_queue = None
        self._lidar_scan_log_stop = threading.Event()
        self._lidar_scan_log_thread = None
        self._lidar_scan_log_dropped_rows = 0
        self._lidar_scan_log_last_enqueue_ms = ""
        self._lidar_scan_log_last_queue_depth = 0
        self._obstacle_slot_log_lock = threading.Lock()
        self._obstacle_slot_log_file = None
        self._obstacle_slot_log_writer = None
        self._obstacle_slot_log_count = 0
        self._obstacle_slot_log_flush_every = max(1, int(getattr(self.args, "obstacle_slot_debug_log_flush_every", 25)))
        self._obstacle_slot_log_queue = None
        self._obstacle_slot_log_stop = threading.Event()
        self._obstacle_slot_log_thread = None
        self._obstacle_slot_log_dropped_rows = 0
        self._obstacle_slot_log_last_enqueue_ms = ""
        self._obstacle_slot_log_last_queue_depth = 0
        self._lidar_apply_trace_log_lock = threading.Lock()
        self._lidar_apply_trace_log_file = None
        self._lidar_apply_trace_log_count = 0
        self._lidar_deferred_debug_queue = None
        self._lidar_deferred_debug_stop = threading.Event()
        self._lidar_deferred_debug_thread = None
        self._lidar_deferred_debug_dropped_rows = 0
        self._lidar_deferred_debug_last_queue_depth = 0
        self._lidar_deferred_debug_last_enqueue_ms = ""
        self._lidar_runtime_update_queue = None
        self._lidar_runtime_update_stop = threading.Event()
        self._lidar_runtime_update_thread = None
        self._lidar_runtime_update_dropped_records = 0
        self._lidar_runtime_update_processed_records = 0
        self._lidar_runtime_update_last_queue_depth = 0
        self._lidar_runtime_update_last_enqueue_ms = ""
        self._lidar_rate_lock = threading.Lock()
        self._lidar_physical_scan_times = deque()
        self._lidar_result_apply_times = deque()
        self.scheduler_probe = SchedulerTimingProbe(self.args, self.shared)
        self.scheduler_probe.start()
        self.lidar_deskew_diagnostic = LidarDeskewDiagnosticRecorder(self.args)
        self._competition_measurement_started = not bool(getattr(self.args, "competition_start_gate", True))
        self._competition_active_announced = not bool(getattr(self.args, "competition_start_gate", True))
        self._startup_lidar_correction_s = max(0.0, float(getattr(self.args, "startup_lidar_correction_s", 0.0) or 0.0))
        self._startup_lidar_correction_start_t = 0.0
        self._startup_lidar_correction_done = self._startup_lidar_correction_s <= 0.0
        self._startup_lidar_policy_phase = "original"
        self._startup_lidar_original_no_correction = bool(getattr(self.args, "no_lidar_correction", False))
        self._startup_lidar_original_mode = str(getattr(self.args, "lidar_correction_mode", "apply") or "apply")
        self._startup_lidar_original_axis_correction = bool(getattr(self.args, "lidar_axis_correction", True))
        self._open_lidar_scan_debug_log()
        self._open_obstacle_slot_debug_log()
        self._open_lidar_apply_trace_log()
        self._start_lidar_scan_log_worker()
        self._start_obstacle_slot_log_worker()
        self._start_lidar_deferred_debug_worker()
        if self.lidar_processing_worker.enabled:
            self._start_lidar_runtime_update_worker()
        if self.lidar_processing_worker.enabled and bool(getattr(self.args, "lidar_processing_worker_immediate_apply", True)):
            self._lidar_processing_apply_thread = threading.Thread(target=self._lidar_processing_worker_apply_loop, daemon=True)
            self._lidar_processing_apply_thread.start()

    def _startup_lidar_correction_fields(self, now: float) -> dict:
        duration_s = max(0.0, float(getattr(self.args, "startup_lidar_correction_s", self._startup_lidar_correction_s) or 0.0))
        self._startup_lidar_correction_s = duration_s
        start_t = float(self._startup_lidar_correction_start_t or 0.0)
        end_t = start_t + duration_s if start_t > 0.0 and duration_s > 0.0 else 0.0
        active = duration_s > 0.0 and start_t > 0.0 and not self._startup_lidar_correction_done and now < end_t
        if active:
            remaining = max(0.0, end_t - now)
        elif self._startup_lidar_correction_done:
            remaining = 0.0
        else:
            remaining = None
        return {
            "startup_lidar_correction_s": duration_s,
            "startup_lidar_correction_start_t": start_t,
            "startup_lidar_correction_end_t": end_t,
            "startup_lidar_correction_remaining_s": remaining,
            "startup_lidar_correction_active": active,
            "startup_lidar_correction_done": bool(self._startup_lidar_correction_done),
        }

    def _set_startup_lidar_correction_policy(self, phase: str) -> None:
        duration_s = max(0.0, float(getattr(self.args, "startup_lidar_correction_s", self._startup_lidar_correction_s) or 0.0))
        self._startup_lidar_correction_s = duration_s
        if duration_s <= 0.0:
            phase = "original"
        phase = str(phase or "original")
        if phase == self._startup_lidar_policy_phase:
            return
        self._startup_lidar_policy_phase = phase
        if phase == "startup_apply":
            self.args.no_lidar_correction = False
            self.args.lidar_correction_mode = "apply"
            self.args.lidar_axis_correction = self._startup_lidar_original_axis_correction
            self.drift_corrector.reset("startup_lidar_correction")
        elif phase == "startup_wait":
            self.args.no_lidar_correction = True
            self.args.lidar_correction_mode = "observe"
            self.args.lidar_axis_correction = False
            self.drift_corrector.reset("startup_lidar_waiting_initial_pose")
        elif phase == "disabled_after_startup":
            self.args.no_lidar_correction = True
            self.args.lidar_correction_mode = "observe"
            self.args.lidar_axis_correction = False
            self.drift_corrector.reset("startup_lidar_disabled_after_hold")
        else:
            self.args.no_lidar_correction = self._startup_lidar_original_no_correction
            self.args.lidar_correction_mode = self._startup_lidar_original_mode
            self.args.lidar_axis_correction = self._startup_lidar_original_axis_correction

    def _competition_state(self, now: Optional[float] = None) -> dict:
        now = time.monotonic() if now is None else float(now)
        enabled = bool(getattr(self.args, "competition_start_gate", True))
        startup_s = max(0.0, float(getattr(self.args, "startup_lidar_correction_s", 0.0) or 0.0))
        if not enabled:
            self._set_startup_lidar_correction_policy("original")
            state = {
                "enabled": False,
                "state": "active",
                "processing_allowed": True,
                "drive_logic_allowed": True,
                "trigger_t": 0.0,
                "measurement_start_t": 0.0,
                "active_t": 0.0,
                "delay_remaining_s": 0.0,
                "initial_hold_remaining_s": 0.0,
                "reason": "disabled",
            }
            state.update(self._startup_lidar_correction_fields(now))
            self.shared.update_competition_start_state(state)
            return state

        snapshot = self.shared.competition_start_snapshot()
        trigger_t = float(snapshot.get("trigger_t", 0.0) or 0.0)
        delay_s = max(0.0, float(getattr(self.args, "competition_start_delay_s", 1.2)))
        hold_s = max(0.0, float(getattr(self.args, "competition_initial_stationary_s", 1.2)))
        if trigger_t <= 0.0:
            self._competition_measurement_started = False
            self._competition_active_announced = False
            self._startup_lidar_correction_start_t = 0.0
            self._startup_lidar_correction_done = startup_s <= 0.0
            self._set_startup_lidar_correction_policy("original")
            state = {
                "enabled": True,
                "state": "waiting_for_start",
                "processing_allowed": False,
                "drive_logic_allowed": False,
                "trigger_t": 0.0,
                "measurement_start_t": 0.0,
                "active_t": 0.0,
                "delay_remaining_s": None,
                "initial_hold_remaining_s": None,
                "reason": "waiting_for_start",
            }
            state.update(self._startup_lidar_correction_fields(now))
            self.shared.update_competition_start_state(state)
            return state

        measurement_start_t = trigger_t + delay_s
        initial_active_t = measurement_start_t + hold_s
        if now < measurement_start_t:
            self._set_startup_lidar_correction_policy("original")
            state = {
                "enabled": True,
                "state": "start_delay",
                "processing_allowed": False,
                "drive_logic_allowed": False,
                "trigger_t": trigger_t,
                "measurement_start_t": measurement_start_t,
                "active_t": initial_active_t,
                "delay_remaining_s": max(0.0, measurement_start_t - now),
                "initial_hold_remaining_s": hold_s,
                "reason": "start_delay",
            }
            state.update(self._startup_lidar_correction_fields(now))
            self.shared.update_competition_start_state(state)
            return state

        if not self._competition_measurement_started:
            self._reset_competition_processing_state(measurement_start_t)
            self._competition_measurement_started = True

        if now < initial_active_t:
            if startup_s > 0.0:
                self._set_startup_lidar_correction_policy("startup_wait")
            else:
                self._set_startup_lidar_correction_policy("original")
            state = {
                "enabled": True,
                "state": "initializing",
                "processing_allowed": True,
                "drive_logic_allowed": False,
                "trigger_t": trigger_t,
                "measurement_start_t": measurement_start_t,
                "active_t": initial_active_t,
                "delay_remaining_s": 0.0,
                "initial_hold_remaining_s": max(0.0, initial_active_t - now),
                "reason": "initial_stationary_hold",
            }
            state.update(self._startup_lidar_correction_fields(now))
            self.shared.update_competition_start_state(state)
            return state

        active_t = initial_active_t
        _pose, _scan, _anchor, _anchor_version, _anchor_source, init_status, _corr = self.shared.snapshot()
        initial_locked = init_status.get("enabled") is False or init_status.get("status") == "locked"
        if not initial_locked:
            if startup_s > 0.0:
                self._set_startup_lidar_correction_policy("startup_wait")
            else:
                self._set_startup_lidar_correction_policy("original")
            state = {
                "enabled": True,
                "state": "waiting_initial_pose",
                "processing_allowed": True,
                "drive_logic_allowed": False,
                "trigger_t": trigger_t,
                "measurement_start_t": measurement_start_t,
                "active_t": initial_active_t,
                "delay_remaining_s": 0.0,
                "initial_hold_remaining_s": 0.0,
                "reason": "waiting_initial_pose",
            }
            state.update(self._startup_lidar_correction_fields(now))
            self.shared.update_competition_start_state(state)
            return state

        if startup_s > 0.0 and not self._startup_lidar_correction_done:
            self._set_startup_lidar_correction_policy("startup_apply")
            if self._startup_lidar_correction_start_t <= 0.0:
                self._startup_lidar_correction_start_t = now
                self.drift_corrector.reset("startup_lidar_correction")
            correction_end_t = self._startup_lidar_correction_start_t + startup_s
            active_t = correction_end_t
            if now < correction_end_t:
                state = {
                    "enabled": True,
                    "state": "startup_lidar_correction",
                    "processing_allowed": True,
                    "drive_logic_allowed": False,
                    "trigger_t": trigger_t,
                    "measurement_start_t": measurement_start_t,
                    "active_t": correction_end_t,
                    "delay_remaining_s": 0.0,
                    "initial_hold_remaining_s": 0.0,
                    "reason": "startup_lidar_correction",
                }
                state.update(self._startup_lidar_correction_fields(now))
                self.shared.update_competition_start_state(state)
                return state
            self._startup_lidar_correction_done = True

        if startup_s > 0.0:
            self._set_startup_lidar_correction_policy("disabled_after_startup")
        else:
            self._set_startup_lidar_correction_policy("original")
        state = {
            "enabled": True,
            "state": "active",
            "processing_allowed": True,
            "drive_logic_allowed": True,
            "trigger_t": trigger_t,
            "measurement_start_t": measurement_start_t,
            "active_t": active_t,
            "delay_remaining_s": 0.0,
            "initial_hold_remaining_s": 0.0,
            "reason": "active",
        }
        state.update(self._startup_lidar_correction_fields(now))
        self.shared.update_competition_start_state(state)
        if not self._competition_active_announced:
            self._competition_active_announced = True
        return state

    def _reset_competition_processing_state(self, measurement_start_t: float) -> None:
        initial_anchor = Pose(t=measurement_start_t, x=self.args.start_x, y=self.args.start_y, h=self.args.start_h)
        self.shared.reset_competition_processing_state(initial_anchor)
        startup_s = max(0.0, float(getattr(self.args, "startup_lidar_correction_s", 0.0) or 0.0))
        self._startup_lidar_correction_s = startup_s
        self._startup_lidar_correction_start_t = 0.0
        self._startup_lidar_correction_done = startup_s <= 0.0
        self.initial_localizer.reset()
        self.drift_corrector.reset("competition_start_reset")
        if self.color_analyzer is not None and getattr(self.color_analyzer, "enabled", False):
            reset_gain = getattr(self.color_analyzer, "reset_analog_gain", None)
            if callable(reset_gain):
                reset_gain()

