    def runtime_debug_status(self) -> dict:
        with self._runtime_debug_lock:
            full_web_debug_enabled = bool(self._runtime_full_web_debug_enabled)
            lite_web_debug_enabled = bool(self._runtime_lite_web_debug_enabled)
            camera_web_debug_enabled = bool(self._runtime_camera_web_debug_enabled)
            camera_web_debug_fps = float(self._runtime_camera_web_debug_fps)
        payload = self.shared.cached_payload() or {}
        race = payload.get("race_timing", {}) if isinstance(payload, dict) else {}
        drive = payload.get("drive_command", {}) if isinstance(payload, dict) else {}
        navigation = payload.get("navigation", {}) if isinstance(payload, dict) else {}
        obstacles = payload.get("obstacles", {}) if isinstance(payload, dict) else {}
        init_status = payload.get("initial_localization", {}) if isinstance(payload, dict) else {}
        competition = payload.get("competition_start", {}) if isinstance(payload, dict) else {}
        return {
            "full_web_debug_enabled": full_web_debug_enabled,
            "lite_web_debug_enabled": lite_web_debug_enabled,
            "camera_web_debug_enabled": camera_web_debug_enabled,
            "camera_web_debug_fps": camera_web_debug_fps,
            "competition_start_state": str(competition.get("state", "")) if isinstance(competition, dict) else "",
            "competition_processing_allowed": bool(competition.get("processing_allowed", False)) if isinstance(competition, dict) else False,
            "competition_drive_logic_allowed": bool(competition.get("drive_logic_allowed", False)) if isinstance(competition, dict) else False,
            "competition_delay_remaining_s": competition.get("delay_remaining_s", "") if isinstance(competition, dict) else "",
            "competition_initial_hold_remaining_s": competition.get("initial_hold_remaining_s", "") if isinstance(competition, dict) else "",
            "race_phase": str(race.get("phase", "")) if isinstance(race, dict) else "",
            "race_mode": str(race.get("mode", "")) if isinstance(race, dict) else "",
            "ranking_time_s": race.get("ranking_time_s", "") if isinstance(race, dict) else "",
            "drive_reason": str(drive.get("reason", "")) if isinstance(drive, dict) else "",
            "drive_source": str(drive.get("source", "")) if isinstance(drive, dict) else "",
            "target_speed_mps": drive.get("target_speed_mps", "") if isinstance(drive, dict) else "",
            "deadman_active": bool((drive.get("deadman", {}) if isinstance(drive, dict) else {}).get("active", False)),
            "deadman_fresh": bool((drive.get("deadman", {}) if isinstance(drive, dict) else {}).get("fresh", False)),
            "deadman_source": str((drive.get("deadman", {}) if isinstance(drive, dict) else {}).get("source", "")),
            "deadman_reason": str((drive.get("deadman", {}) if isinstance(drive, dict) else {}).get("reason", "")),
            "deadman_gpio_level": (drive.get("deadman", {}) if isinstance(drive, dict) else {}).get("gpio_level", ""),
            "navigation_section": str(navigation.get("section", "")) if isinstance(navigation, dict) else "",
            "full_gate_lock": bool(navigation.get("full_gate_lock", False)) if isinstance(navigation, dict) else False,
            "obstacle_detection_enabled": bool(obstacles.get("detection_enabled", False)) if isinstance(obstacles, dict) else False,
            "known_obstacles": obstacles.get("known_count", "") if isinstance(obstacles, dict) else "",
            "initial_status": str(init_status.get("status", "")) if isinstance(init_status, dict) else "",
        }

