    def _refresh_control_runtime_payload(self, navigation_debug: dict, drive_command: dict, now: float) -> dict:
        hz = float(getattr(self.args, "web_payload_refresh_hz", 10.0) or 0.0)
        cached = self.shared.cached_payload()
        force_full = cached is None or hz <= 0.0
        if not force_full:
            min_period = 1.0 / max(hz, 0.001)
            force_full = (now - float(self._control_payload_last_full_t or 0.0)) >= min_period
        if force_full:
            payload = self.shared.refresh_runtime_payload(self.args, navigation_debug, drive_command, now)
            self._control_payload_last_full_t = now
            self.shared.record_metric(
                "control_payload_refresh",
                {
                    "mode": "full",
                    "configured_hz": hz,
                    "skipped_since_full": self._control_payload_skipped,
                    "cached_payload": int(cached is not None),
                },
            )
            self._control_payload_skipped = 0
            return payload
        self._control_payload_skipped += 1
        payload = self.shared.refresh_runtime_payload_light(self.args, navigation_debug, drive_command, now)
        self._control_payload_last_light_t = now
        self.shared.record_metric(
            "control_payload_refresh",
            {
                "mode": "light",
                "configured_hz": hz,
                "skipped_since_full": self._control_payload_skipped,
                "cached_payload": 1,
                "last_full_age_ms": (now - float(self._control_payload_last_full_t or 0.0)) * 1000.0
                if self._control_payload_last_full_t
                else "",
            },
        )
        return payload

    def update_control_preview(self) -> dict:
        update_start = time.monotonic()
        now = update_start
        competition_start = self._competition_state(now)
        if not bool(competition_start.get("drive_logic_allowed", True)):
            reason = str(competition_start.get("reason", "competition_start") or "competition_start")
            navigation_debug = {
                "enabled": False,
                "reason": reason,
                "pose_confidence_ok": False,
                "path": [],
                "competition_start": dict(competition_start),
            }
            drive_command = self.shared.update_competition_wait_command(reason, now, brake=True)
            race_timing = self.shared.update_race_timing(navigation_debug, drive_command, self.args, now)
            navigation_debug["race_timing"] = race_timing
            self.shared.record_timing("control_update", update_start)
            return self._refresh_control_runtime_payload(navigation_debug, drive_command, now)

        pose, _scan, anchor, anchor_version, anchor_source, init_status, _correction_status = self.shared.snapshot()
        init_locked = init_status.get("enabled") is False or str(init_status.get("status", "") or "") == "locked"
        if bool(competition_start.get("enabled", True)) and not init_locked:
            reason = "init_not_locked"
            navigation_debug = {
                "enabled": False,
                "reason": reason,
                "pose_confidence_ok": False,
                "path": [],
                "competition_start": dict(competition_start),
                "initial_status": str(init_status.get("status", "") or ""),
            }
            drive_command = self.shared.update_competition_wait_command(reason, now, brake=True)
            race_timing = self.shared.update_race_timing(navigation_debug, drive_command, self.args, now)
            navigation_debug["race_timing"] = race_timing
            self.shared.record_timing("control_update", update_start)
            return self._refresh_control_runtime_payload(navigation_debug, drive_command, now)
        display_pose = local_to_display_pose(pose, anchor)
        runtime = self.shared.runtime_perception_snapshot()
        passive_color_status = self.shared.update_unpark_passive_color_confirmation(display_pose, self.args, now, init_status)
        if passive_color_status.get("committed_color"):
            runtime = self.shared.runtime_perception_snapshot()
        lidar_estimate = runtime.get("lidar_estimate") or LidarPoseEstimate(valid=False, reason="no lidar estimate")
        obstacle_results = runtime.get("obstacles", []) or []
        navigation_args = self.args
        locked_direction = init_status.get("navigation_direction", "")
        navigation_free_race = effective_free_race(self.args, init_status)
        race_snapshot = self.shared.race_timing_snapshot()
        unpark_snapshot = self.shared.unpark_snapshot()
        smart_parking_snapshot = self.shared.smart_parking_snapshot()
        race_phase = str(race_snapshot.get("phase", "") or "")
        if (
            navigation_free_race
            and bool(getattr(self.args, "free_race_adaptive_inner_route", True))
            and (bool(race_snapshot.get("lap1_gate_t", 0.0)) or int(race_snapshot.get("full_gate_pass_count", 0) or 0) >= 1)
        ):
            current_inner = runtime.get("free_race_inner_config", {}) if isinstance(runtime, dict) else {}
            if not isinstance(current_inner, dict) or not bool(current_inner.get("locked", False)):
                locked_inner = self.shared.lock_free_race_inner_config(now, self.args, "lap1_complete_control")
                runtime = dict(runtime)
                runtime["free_race_inner_config"] = locked_inner
        unpark_state = str(unpark_snapshot.get("state", "") or "")
        init_source = str(init_status.get("source", "") or "")
        init_decision = str(init_status.get("parking_decision", "") or "")
        unpark_pending = (
            bool(getattr(self.args, "unpark_after_parking_start", True))
            and init_locked
            and init_source in ("simple_parking_start", "startup_classifier_parking")
            and init_decision in ("PARK_CLOCK", "PARK_COUNTER")
            and unpark_state in ("", "idle")
        )
        unpark_active = unpark_state not in ("", "idle", "done") or unpark_pending
        smart_parking_state = str(smart_parking_snapshot.get("state", "") or "")
        smart_parking_active = smart_parking_state not in ("", "idle", "done", "free_race_done")
        competition_drive_allowed = bool(competition_start.get("drive_logic_allowed", True))
        if not competition_drive_allowed:
            confirmations_active = False
            confirmations_active_reason = "competition_wait"
        elif not init_locked:
            confirmations_active = False
            confirmations_active_reason = "init_not_locked"
        elif navigation_free_race:
            confirmations_active = False
            confirmations_active_reason = "free_race"
        elif unpark_active:
            confirmations_active = False
            confirmations_active_reason = "unpark_pending" if unpark_pending else "unpark_active"
        elif smart_parking_active:
            confirmations_active = False
            confirmations_active_reason = "smart_parking_active"
        else:
            confirmations_active = True
            confirmations_active_reason = "active" if race_phase == "navigation" else f"active_race_phase_{race_phase or 'empty'}"
        if (
            getattr(self.args, "navigation_direction", "auto") == "auto"
            and locked_direction in ("CLOCK", "COUNTER")
        ) or navigation_free_race != bool(getattr(self.args, "navigation_free_race", False)):
            navigation_args = SimpleNamespace(**vars(self.args))
            navigation_args.navigation_free_race = navigation_free_race
            navigation_args.free_race = navigation_free_race and getattr(self.args, "race_mode", "auto") == "free"
        if getattr(self.args, "navigation_direction", "auto") == "auto" and locked_direction in ("CLOCK", "COUNTER"):
            if navigation_args is self.args:
                navigation_args = SimpleNamespace(**vars(self.args))
            navigation_args.navigation_locked_direction = locked_direction
        if navigation_args is self.args:
            navigation_args = SimpleNamespace(**vars(self.args))
        navigation_args.free_race_inner_config = dict(runtime.get("free_race_inner_config") or self.shared.free_race_inner_config_snapshot())
        navigation_args.navigation_confirmations_active = confirmations_active
        navigation_args.navigation_confirmations_active_reason = confirmations_active_reason
        navigation_args.navigation_race_phase = race_phase
        navigation_args.navigation_unpark_state = unpark_state
        navigation_args.navigation_unpark_pending = unpark_pending
        with self.shared.lock:
            anchor_diagnostics = dict(self.shared.anchor_diagnostics)
        navigation_args.navigation_smart_parking_state = smart_parking_state
        navigation_args.navigation_initial_pose_locked = init_locked
        navigation_args.navigation_state_mutations_allowed = init_locked
        navigation_args.navigation_initial_status = str(init_status.get("status", "") or "")
        navigation_args.navigation_anchor_version = int(anchor_version)
        navigation_args.navigation_anchor_source = str(anchor_source)
        navigation_args.navigation_anchor_last_jump_m = anchor_diagnostics.get("jump_m", 0.0)
        navigation_args.navigation_anchor_last_jump_h_deg = anchor_diagnostics.get("jump_h_deg", 0.0)
        navigation_args.navigation_anchor_last_source = str(anchor_diagnostics.get("source", "") or "")
        navigation_args.navigation_anchor_last_rejected = bool(anchor_diagnostics.get("rejected", False))
        navigation_deadman = self.shared._simple_drive_deadman(now)
        navigation_args.navigation_deadman_active = bool(navigation_deadman.get("fresh", False)) and bool(navigation_deadman.get("active", False))
        navigation_args.navigation_timing_warning = str(race_snapshot.get("warning", "") or "")
        navigation_args.localization_hold = self.shared.localization_hold_snapshot(self.args, now)
        navigation_args.competition_start = competition_start
        if build_navigation_debug is not None:
            navigation_debug = build_navigation_debug(display_pose, lidar_estimate, obstacle_results, navigation_args)
        else:
            navigation_debug = {"enabled": False, "reason": "navigation unavailable"}
        navigation_debug["competition_start"] = dict(competition_start)
        self.shared.update_localization_hold_navigation_context(navigation_debug, now)
        color_commit = {}
        if isinstance(navigation_debug.get("color_confirmation"), dict):
            color_commit = dict(navigation_debug.get("color_confirmation", {}).get("commit_color", {}) or {})
        if color_commit:
            self.shared.commit_obstacle_color_decision(
                str(color_commit.get("slot_id", "")),
                str(color_commit.get("color", "")),
                float(color_commit.get("confidence", 0.0) or 0.0),
                str(color_commit.get("source", "")),
            )
        color_status = navigation_debug.get("color_confirmation", {}) if isinstance(navigation_debug, dict) else {}
        gain_request = color_status.get("camera_gain_request", {}) if isinstance(color_status, dict) else {}
        if self.color_analyzer is not None and self.color_analyzer.enabled:
            if isinstance(gain_request, dict) and bool(gain_request.get("active", False)):
                self.color_analyzer.set_analog_gain(float(gain_request.get("gain", getattr(self.args, "camera_analog_gain", 14.0)) or getattr(self.args, "camera_analog_gain", 14.0)))
            else:
                self.color_analyzer.reset_analog_gain()
        drive_command = self.shared.update_drive_command_preview(navigation_debug, navigation_args, now)
        race_timing = self.shared.update_race_timing(navigation_debug, drive_command, navigation_args, now)
        navigation_debug["race_timing"] = race_timing
        self.shared.record_timing("control_update", update_start)
        return self._refresh_control_runtime_payload(navigation_debug, drive_command, now)

    def lite_payload(self) -> dict:
        return build_lite_payload(self.shared, self.args)

    def payload(self) -> dict:
        stage_start = time.monotonic()
        try:
            hz = float(getattr(self.args, "web_payload_refresh_hz", 10.0) or 0.0)
        except (TypeError, ValueError):
            hz = 10.0
        now = stage_start
        cached = self.shared.cached_payload()
        if cached is not None and hz > 0.0 and self._web_payload_last_full_t > 0.0:
            min_period = 1.0 / max(hz, 0.001)
            if now - self._web_payload_last_full_t < min_period:
                self._web_payload_cached_count += 1
                self.shared.record_timing("web_payload_cached", stage_start)
                self.shared.record_metric(
                    "web_payload_refresh_control",
                    {
                        "mode": "cached",
                        "configured_hz": hz,
                        "cached_count": self._web_payload_cached_count,
                        "last_full_age_ms": (now - self._web_payload_last_full_t) * 1000.0,
                    },
                )
                return cached
        payload = build_payload(self.shared, self.args, self.color_analyzer)
        self._web_payload_last_full_t = time.monotonic()
        self.shared.record_timing("web_payload_refresh", stage_start)
        self.shared.record_metric(
            "web_payload_refresh_control",
            {
                "mode": "full",
                "configured_hz": hz,
                "cached_count": self._web_payload_cached_count,
                "last_full_age_ms": 0.0,
            },
        )
        return payload

    def _scan_times(self, scan: LidarScanInput, count: int, receive_t: float) -> tuple[float, float, float, str]:
        duration = float(scan.scan_time or 0.0)
        increment = float(scan.time_increment or 0.0)
        if duration <= 0.0 and increment > 0.0:
            duration = increment * max(count - 1, 0)
        if increment <= 0.0 and count > 1 and duration > 0.0:
            increment = duration / (count - 1)

        if self.args.lidar_timestamp_mode == "header" and scan.header_stamp_s > 0.0 and scan.ros_now_s > 0.0:
            start_t = float(scan.header_stamp_s) + (receive_t - float(scan.ros_now_s)) + self.args.lidar_time_offset_s
            return start_t, start_t + duration, increment, "header"

        end_t = receive_t - self.args.lidar_latency_s
        if self.args.lidar_timestamp_mode == "receive-start":
            start_t = end_t
            end_t = start_t + duration
            return start_t, end_t, increment, "receive-start"
        start_t = end_t - duration
        end_t = start_t + duration
        return start_t, end_t, increment, "receive"

    def _sector_distance(self, ranges: np.ndarray, degs: np.ndarray, start_deg: float, end_deg: float) -> float:
        start_deg %= 360.0
        end_deg %= 360.0
        if start_deg <= end_deg:
            mask = (degs >= start_deg) & (degs <= end_deg)
        else:
            mask = (degs >= start_deg) | (degs <= end_deg)
        vals = ranges[mask]
        vals = vals[np.isfinite(vals)]
        vals = vals[(vals >= float(self.args.lidar_min_range_m)) & (vals <= self.args.init_simple_parking_max_range_m)]
        if vals.size < self.args.init_simple_parking_min_sector_points:
            return float("inf")
        return float(np.median(vals))

    def _simple_parking_decision(self, ranges: np.ndarray, angles: np.ndarray) -> str:
        if not self.args.init_simple_parking_start:
            return "UNKNOWN"
        degs = np.degrees(angles) % 360.0
        d_front = self._sector_distance(
            ranges,
            degs,
            self.args.init_simple_parking_front_min_deg,
            self.args.init_simple_parking_front_max_deg,
        )
        if d_front > self.args.init_simple_parking_front_m:
            return "NO_PARK"
        d_left = self._sector_distance(
            ranges,
            degs,
            self.args.init_simple_parking_left_min_deg,
            self.args.init_simple_parking_left_max_deg,
        )
        d_right = self._sector_distance(
            ranges,
            degs,
            self.args.init_simple_parking_right_min_deg,
            self.args.init_simple_parking_right_max_deg,
        )
        side_limit = self.args.init_simple_parking_side_m
        side_delta = self.args.init_simple_parking_side_delta_m
        left_close = d_left <= side_limit
        right_close = d_right <= side_limit
        if left_close and (not right_close or d_right - d_left >= side_delta):
            return "PARK_CLOCK"
        if right_close and (not left_close or d_left - d_right >= side_delta):
            return "PARK_COUNTER"
        return "PARK_UNKNOWN"


    def _timing_duration_entry(self, name: str, duration_ms) -> tuple[str, float, float]:
        try:
            duration = max(0.0, float(duration_ms or 0.0)) / 1000.0
        except Exception:
            duration = 0.0
        end = time.monotonic()
        return (name, end - duration, end)

    def _record_timing_duration_ms(self, name: str, duration_ms, profile: Optional[dict] = None, profile_prefix: str = "") -> None:
        timing_name, start_t, end_t = self._timing_duration_entry(name, duration_ms)
        self.shared.record_timing(timing_name, start_t, end_t, profile=profile, profile_prefix=profile_prefix or f"{name}_record_timing")

    def _processing_worker_state(self, reference_t: float) -> tuple[dict, int, tuple]:
        pose, _scan, anchor, anchor_version, _anchor_source, init_status, _corr = self.shared.snapshot()
        mode = effective_race_mode(self.args, init_status)
        mode_args = perception_args_for_mode(self.args, init_status)
        mode_signature = tuple(lidar_view_cache_key(0.0, 0, mode_args, True)[2:])
        obstacle_ready, obstacle_reason = obstacle_detection_allowed_for_scan(self.shared, init_status, mode)
        with self.shared.lock:
            history = [(p.t, p.x, p.y, p.h, p.vx, p.vy, p.vh) for p in self.shared.otos_history]
            current_pose = self.shared.otos
            anchor_snapshot = self.shared.anchor
            known_before = set(self.shared.known_obstacle_slots)
        local_reference_pose = _pose_at_from_history(reference_t, history, current_pose)
        reference_pose = local_to_display_pose(local_reference_pose, anchor_snapshot)
        obstacle_yaw_gate = obstacle_detection_yaw_gate_status(reference_pose, self.args)
        if obstacle_ready and bool(obstacle_yaw_gate.get("gated", False)):
            obstacle_ready = False
            obstacle_reason = "yaw_rate_gate"
        state = {
            "pose": pose,
            "anchor": anchor_snapshot,
            "anchor_version": anchor_version,
            "init_status": dict(init_status),
            "mode": mode,
            "mode_args": mode_args,
            "mode_signature": mode_signature,
            "obstacle_detection_ready": bool(obstacle_ready),
            "obstacle_detection_reason": obstacle_reason,
            "obstacle_detection_yaw_gate": obstacle_yaw_gate,
            "pose_history": history,
            "current_pose": current_pose,
            "known_before": known_before,
            "reference_t": reference_t,
        }
        return state, anchor_version, mode_signature


    def _worker_apply_profile_start(self):
        profile_thread_time = getattr(time, "thread_time", None)
        return (
            time.monotonic(),
            time.process_time(),
            profile_thread_time() if profile_thread_time is not None else None,
        )

    def _worker_apply_profile_finish(self, start):
        profile_thread_time = getattr(time, "thread_time", None)
        end_wall = time.monotonic()
        end_process = time.process_time()
        end_thread = profile_thread_time() if profile_thread_time is not None else None
        start_thread = start[2]
        return {
            "wall_ms": max(0.0, (end_wall - start[0]) * 1000.0),
            "process_cpu_ms": max(0.0, (end_process - start[1]) * 1000.0),
            "thread_cpu_ms": "" if end_thread is None or start_thread is None else max(0.0, (end_thread - start_thread) * 1000.0),
        }

    def _lidar_rate_fields(self) -> dict:
        def _rate_for_window(times: deque, window_s: float, now: float) -> float:
            values = [float(t) for t in times if now - float(t) <= window_s]
            if len(values) < 2:
                return 0.0
            span = max(1e-6, values[-1] - values[0])
            return float((len(values) - 1) / span)

        now = time.monotonic()
        with self._lidar_rate_lock:
            while self._lidar_physical_scan_times and now - float(self._lidar_physical_scan_times[0]) > 3.5:
                self._lidar_physical_scan_times.popleft()
            while self._lidar_result_apply_times and now - float(self._lidar_result_apply_times[0]) > 3.5:
                self._lidar_result_apply_times.popleft()
            physical = deque(self._lidar_physical_scan_times)
            applied = deque(self._lidar_result_apply_times)
        return {
            "lidar_physical_hz_1s": _rate_for_window(physical, 1.0, now),
            "lidar_physical_hz_3s": _rate_for_window(physical, 3.0, now),
            "lidar_result_applied_hz_1s": _rate_for_window(applied, 1.0, now),
            "lidar_result_applied_hz_3s": _rate_for_window(applied, 3.0, now),
        }

    def _record_lidar_rate_event(self, kind: str, event_t: Optional[float] = None) -> dict:
        t = time.monotonic() if event_t is None else float(event_t)
        with self._lidar_rate_lock:
            if kind == "physical_scan":
                self._lidar_physical_scan_times.append(t)
            elif kind == "worker_result_apply":
                self._lidar_result_apply_times.append(t)
        return self._lidar_rate_fields()

    def _write_lidar_processing_worker_reject_rows(self, poll_debug: Optional[dict], poll_profile: Optional[dict] = None) -> None:
        if self._lidar_scan_log_writer is None or not isinstance(poll_debug, dict):
            return
        details = poll_debug.get("processing_worker_reject_details")
        if not isinstance(details, list) or not details:
            return
        try:
            timings = self.shared.timing_snapshot()
        except Exception:
            timings = {}
        try:
            race = self.shared.race_timing_snapshot() or {}
        except Exception:
            race = {}
        try:
            competition = self.shared.competition_start_snapshot() or {}
        except Exception:
            competition = {}
        poll_profile = dict(poll_profile or {})
        rate_fields = self._lidar_rate_fields()
        scan_id = int((timings.get("lidar_process", {}) if isinstance(timings, dict) else {}).get("count", 0) or 0)
        for detail in details:
            if not isinstance(detail, dict):
                continue
            reason = str(detail.get("reason", "") or "")
            if reason == "superseded_by_newer_result":
                row_kind = "worker_result_superseded"
            elif reason.startswith("anchor_rebase"):
                row_kind = "worker_result_rebase_reject"
            else:
                row_kind = "worker_result_reject"
            self._write_lidar_scan_debug_row(
                {
                    "scan_id": scan_id,
                    "lidar_row_kind": row_kind,
                    **rate_fields,
                    "t": f"{time.monotonic():.6f}",
                    "scan_mid_t": f"{float(detail.get('scan_t', 0.0) or 0.0):.6f}" if detail.get("scan_t", "") != "" else "",
                    "async_worker_poll_ms": poll_profile.get("wall_ms", ""),
                    "async_worker_poll_process_cpu_ms": poll_profile.get("process_cpu_ms", ""),
                    "async_worker_poll_thread_cpu_ms": poll_profile.get("thread_cpu_ms", ""),
                    "lidar_worker_enabled": 1,
                    "lidar_worker_status": row_kind,
                    "lidar_worker_mode": "full_processing_async",
                    "lidar_worker_request_id": detail.get("request_id", ""),
                    "lidar_worker_latest_result_id": detail.get("latest_result_id", poll_debug.get("processing_worker_latest_result_id", "")),
                    "lidar_worker_applied": 0,
                    "lidar_worker_reject_reason": reason,
                    "lidar_worker_pending": poll_debug.get("processing_worker_pending", ""),
                    "lidar_worker_rejected_results": poll_debug.get("processing_worker_rejected_results", detail.get("rejected_count_after", "")),
                    "lidar_worker_superseded_results": poll_debug.get("processing_worker_superseded_results", detail.get("superseded_count_after", "")),
                    "lidar_worker_reject_event_reason": reason,
                    "lidar_worker_reject_event_request_id": detail.get("request_id", ""),
                    "lidar_worker_reject_event_latest_result_id": detail.get("latest_result_id", ""),
                    "lidar_worker_reject_event_accepted_request_id": detail.get("accepted_request_id", ""),
                    "lidar_worker_reject_event_scan_t": detail.get("scan_t", ""),
                    "lidar_worker_reject_event_worker_finish_t": detail.get("worker_finish_t", ""),
                    "lidar_worker_reject_event_worker_wall_ms": detail.get("worker_wall_ms", ""),
                    "lidar_worker_reject_event_scan_age_ms": detail.get("scan_age_ms", ""),
                    "lidar_worker_reject_event_receive_age_ms": detail.get("receive_age_ms", ""),
                    "lidar_worker_reject_event_current_anchor_version": detail.get("current_anchor_version", ""),
                    "lidar_worker_reject_event_result_anchor_version": detail.get("result_anchor_version", ""),
                    "lidar_worker_reject_event_anchor_version_delta": detail.get("anchor_version_delta", ""),
                    "lidar_worker_anchor_rebase_candidate": detail.get("anchor_rebase_candidate", ""),
                    "lidar_worker_anchor_rebased": detail.get("anchor_rebased", ""),
                    "lidar_worker_anchor_rebase_method": detail.get("anchor_rebase_method", ""),
                    "lidar_worker_anchor_rebase_reject_reason": detail.get("anchor_rebase_reject_reason", ""),
                    "lidar_worker_anchor_rebase_dx_m": detail.get("anchor_rebase_dx_m", ""),
                    "lidar_worker_anchor_rebase_dy_m": detail.get("anchor_rebase_dy_m", ""),
                    "lidar_worker_anchor_rebase_dh_deg": detail.get("anchor_rebase_dh_deg", ""),
                    "lidar_worker_anchor_rebase_dist_m": detail.get("anchor_rebase_dist_m", ""),
                    "lidar_worker_anchor_rebase_refit_ms": detail.get("anchor_rebase_refit_ms", ""),
                    "lidar_worker_anchor_rebase_refit_valid": detail.get("anchor_rebase_refit_valid", ""),
                    "lidar_worker_anchor_rebase_refit_confidence": detail.get("anchor_rebase_refit_confidence", ""),
                    "lidar_worker_anchor_rebase_refit_reason": detail.get("anchor_rebase_refit_reason", ""),
                    "lidar_worker_reject_event_current_mode_signature": detail.get("current_mode_signature", ""),
                    "lidar_worker_reject_event_result_mode_signature": detail.get("result_mode_signature", ""),
                    "lidar_worker_reject_event_mode_signature_match": detail.get("mode_signature_match", ""),
                    "lidar_worker_reject_event_ok": detail.get("ok", ""),
                    "lidar_worker_reject_event_error": detail.get("error", ""),
                    "lidar_worker_reject_event_drained_count": detail.get("drained_count", ""),
                    "lidar_worker_reject_event_counter_after": detail.get("rejected_count_after", ""),
                    "lidar_worker_superseded_event_counter_after": detail.get("superseded_count_after", ""),
                    "race_phase": race.get("phase", ""),
                    "race_mode": race.get("mode", ""),
                    "competition_start_state": str(competition.get("state", "")),
                    "competition_processing_allowed": int(bool(competition.get("processing_allowed", True))),
                    "competition_drive_logic_allowed": int(bool(competition.get("drive_logic_allowed", True))),
                }
            )

    def _reserve_lidar_processing_apply(self, request_id: int):
        def _reserve() -> bool:
            if request_id and request_id <= int(getattr(self, "_last_lidar_processing_applied_request_id", 0) or 0):
                return False
            if request_id:
                self._last_lidar_processing_applied_request_id = max(
                    int(getattr(self, "_last_lidar_processing_applied_request_id", 0) or 0),
                    int(request_id),
                )
            return True

        return _LidarApplyReservation(self._lidar_processing_apply_lock, _reserve)

    def _lidar_processing_result_args(self, result: dict):
        mode_args = SimpleNamespace(**vars(self.args))
        for key, value in dict(result.get("arg_overrides", {}) or {}).items():
            try:
                setattr(mode_args, key, value)
            except Exception:
                pass
        return mode_args

    def _snapshot_from_lidar_processing_result(self, result: dict) -> ScanSnapshot:
        return ScanSnapshot(
            t=float(result.get("scan_t", 0.0) or 0.0),
            start_t=float(result.get("scan_start_t", 0.0) or 0.0),
            end_t=float(result.get("scan_end_t", 0.0) or 0.0),
            points_lidar=np.asarray(result.get("points_lidar", np.empty((0, 2), dtype=float)), dtype=float),
            points_field=np.asarray(result.get("points_field", np.empty((0, 2), dtype=float)), dtype=float),
            point_times=np.asarray(result.get("point_times", np.empty(0, dtype=float)), dtype=float),
            reference_pose=result.get("reference_pose") if isinstance(result.get("reference_pose"), Pose) else _pose_from_dict(result.get("reference_pose")),
            reference_local_pose=_optional_pose_from_dict(result.get("reference_local_pose")),
            timestamp_source=str(result.get("timestamp_source", "") or ""),
            beam_time_order=str(result.get("beam_time_order", "forward") or "forward"),
            deskewed=bool(result.get("deskewed", False)),
        )

