        self._record_timing_duration_ms("lidar_stage_runtime_update", runtime_profile.get("wall_ms", 0.0))
        self.shared.record_timing("lidar_stage_payload_build", time.monotonic(), time.monotonic())
        submit_debug, _submit_state, _submit_anchor_version, _submit_mode_signature = _submit_current_scan_request()
