        def _profile_value(profile_name: str, key: str):
            if profile_name == "process":
                values = {"wall_ms": total_process_ms, "process_cpu_ms": process_profile.get("process_cpu_ms", ""), "thread_cpu_ms": ""}
            elif profile_name == "snapshot":
                values = snapshot_profile
            elif profile_name == "localization_correction":
                values = localization_profile
            elif profile_name == "runtime_update":
                values = runtime_profile
            elif profile_name == "async_worker_poll":
                values = poll_profile
            else:
                values = stage_profiles.get(profile_name, {})
            return values.get(key, "") if isinstance(values, dict) else ""

