    def close(self) -> None:
        self._lidar_processing_apply_stop.set()
        scheduler_probe = getattr(self, "scheduler_probe", None)
        if scheduler_probe is not None:
            try:
                scheduler_probe.stop()
            except Exception:
                pass
        apply_thread = getattr(self, "_lidar_processing_apply_thread", None)
        if apply_thread is not None:
            try:
                apply_thread.join(timeout=0.6)
            except Exception:
                pass
            self._lidar_processing_apply_thread = None
        try:
            self._stop_lidar_runtime_update_worker()
        except Exception:
            pass
        processing_worker = getattr(self, "lidar_processing_worker", None)
        if processing_worker is not None:
            try:
                processing_worker.close()
            except Exception:
                pass
        worker = getattr(self, "lidar_pose_worker", None)
        if worker is not None:
            try:
                worker.close()
            except Exception:
                pass
        cloud_worker = getattr(self, "cloud_wall_diagnostic_worker", None)
        if cloud_worker is not None:
            try:
                cloud_worker.close()
            except Exception:
                pass
        corrector = getattr(self, "drift_corrector", None)
        if corrector is not None:
            try:
                corrector.close()
            except Exception:
                pass
        try:
            self._stop_lidar_deferred_debug_worker()
        except Exception:
            pass
        recorder = getattr(self, "lidar_deskew_diagnostic", None)
        if recorder is not None:
            try:
                recorder.close()
            except Exception:
                pass
        analyzer = self.color_analyzer
        close = getattr(analyzer, "close", None)
        if callable(close):
            close()
        try:
            self._stop_obstacle_slot_log_worker()
        except Exception:
            pass
        try:
            self._stop_lidar_scan_log_worker()
        except Exception:
            pass
        if self._lidar_apply_trace_log_file is not None:
            try:
                self._lidar_apply_trace_log_file.flush()
                self._lidar_apply_trace_log_file.close()
            except Exception:
                pass
            self._lidar_apply_trace_log_file = None
        if self._lidar_scan_log_file is not None:
            try:
                self._lidar_scan_log_file.flush()
                self._lidar_scan_log_file.close()
            except Exception:
                pass
            self._lidar_scan_log_file = None
            self._lidar_scan_log_writer = None
        if self._obstacle_slot_log_file is not None:
            try:
                self._obstacle_slot_log_file.flush()
                self._obstacle_slot_log_file.close()
            except Exception:
                pass
            self._obstacle_slot_log_file = None
            self._obstacle_slot_log_writer = None
